import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage, SignupPage } from "./src/pages/auth" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };
import { getNotifications, getNotificationPreferences } from "./src/queries" with { type: "ref" };
import {
  batchUpdateNotificationStatus,
  updateNotificationPreferences,
  triggerNotificationEvent,
} from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    query(getNotifications, { entities: ["Notification"] }),
    action(batchUpdateNotificationStatus, { entities: ["Notification"] }),

    query(getNotificationPreferences, { entities: ["NotificationPreference"] }),
    action(updateNotificationPreferences, {
      entities: ["NotificationPreference", "User"],
    }),

    action(triggerNotificationEvent, {
      entities: ["Notification", "NotificationPreference", "User"],
    }),
  ],
});

import { type WebSocketDefinition, type WaspSocketData } from "wasp/server/webSocket";
import { type Notification } from "wasp/entities";

// Typing our WebSocket function with the events and payloads
// allows us to get type safety on the client as well.
type WebSocketFn = WebSocketDefinition<
  ClientToServerEvents,
  ServerToClientEvents,
  InterServerEvents,
  SocketData
>;

interface ServerToClientEvents {
  notification: (notification: Notification) => void;
}

// This app doesn't need the client to send anything to the server over
// WebSockets, but Socket.IO requires the type to be declared.
interface ClientToServerEvents {
  // No client -> server events for this app.
  _placeholder?: never;
}

interface InterServerEvents {
  _placeholder?: never;
}

// Data that is attached to the socket.
// NOTE: Wasp automatically injects the JWT into the connection,
// and if present/valid, the server adds a user to the socket.
interface SocketData extends WaspSocketData {}

// Critical seam: server-side Operations (e.g. Actions) need a way to emit
// WebSocket events. We keep a module-level reference to the `io` instance
// Wasp gives us here, and export a getter so other server code can use it.
let ioInstance: Parameters<WebSocketFn>[0] | undefined;

export function getIo() {
  return ioInstance;
}

export const webSocketFn: WebSocketFn = (io, _context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    const userId = socket.data.user?.id;
    if (userId !== undefined) {
      socket.join(`user-${userId}`);
    }
  });
};

import { HttpError } from "wasp/server";
import { type GetNotifications, type GetNotificationPreferences } from "wasp/server/operations";
import { type Notification, type NotificationPreference } from "wasp/entities";

export const getNotifications: GetNotifications<void, Notification[]> = async (
  _args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Notification.findMany({
    where: { userId: context.user.id },
    orderBy: { createdAt: "desc" },
  });
};

export const getNotificationPreferences: GetNotificationPreferences<
  void,
  NotificationPreference
> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const existingPreference = await context.entities.NotificationPreference.findUnique({
    where: { userId: context.user.id },
  });

  if (existingPreference) {
    return existingPreference;
  }

  return context.entities.NotificationPreference.create({
    data: {
      userId: context.user.id,
      systemEnabled: true,
      securityEnabled: true,
      activityEnabled: true,
    },
  });
};

import { HttpError } from "wasp/server";
import {
  type BatchUpdateNotificationStatus,
  type UpdateNotificationPreferences,
  type TriggerNotificationEvent,
} from "wasp/server/operations";
import { type NotificationPreference } from "wasp/entities";
import { getIo } from "./webSocket";

type NotificationType = "SYSTEM" | "SECURITY" | "ACTIVITY";

export const batchUpdateNotificationStatus: BatchUpdateNotificationStatus<
  { ids: number[]; isRead: boolean },
  { count: number }
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const result = await context.entities.Notification.updateMany({
    where: {
      id: { in: args.ids },
      userId: context.user.id,
    },
    data: { isRead: args.isRead },
  });

  return { count: result.count };
};

export const updateNotificationPreferences: UpdateNotificationPreferences<
  { systemEnabled: boolean; securityEnabled: boolean; activityEnabled: boolean },
  NotificationPreference
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.NotificationPreference.upsert({
    where: { userId: context.user.id },
    update: {
      systemEnabled: args.systemEnabled,
      securityEnabled: args.securityEnabled,
      activityEnabled: args.activityEnabled,
    },
    create: {
      userId: context.user.id,
      systemEnabled: args.systemEnabled,
      securityEnabled: args.securityEnabled,
      activityEnabled: args.activityEnabled,
    },
  });
};

export const triggerNotificationEvent: TriggerNotificationEvent<
  { type: NotificationType; title: string; message: string },
  { success: true; created: boolean }
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const preference = await context.entities.NotificationPreference.findUnique({
    where: { userId: context.user.id },
  });

  const isEnabledForType = (() => {
    if (!preference) {
      // No preference record yet: default to enabled (matches the
      // default `true` values used when a preference record is created).
      return true;
    }
    switch (args.type) {
      case "SYSTEM":
        return preference.systemEnabled;
      case "SECURITY":
        return preference.securityEnabled;
      case "ACTIVITY":
        return preference.activityEnabled;
      default:
        return false;
    }
  })();

  if (!isEnabledForType) {
    return { success: true, created: false };
  }

  const notification = await context.entities.Notification.create({
    data: {
      userId: context.user.id,
      type: args.type,
      title: args.title,
      message: args.message,
    },
  });

  const io = getIo();
  if (io) {
    io.to(`user-${context.user.id}`).emit("notification", notification);
  }

  return { success: true, created: true };
};

